import{_ as a,c as n,o as r,ag as t}from"./chunks/framework.ARG558ZT.js";const g=JSON.parse('{"title":"Frontend coverage and ownership map","description":"","frontmatter":{},"headers":[],"relativePath":"frontend/coverage-map.md","filePath":"frontend/coverage-map.md"}'),o={name:"frontend/coverage-map.md"};function s(i,e,c,d,h,l){return r(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="frontend-coverage-and-ownership-map" tabindex="-1">Frontend coverage and ownership map <a class="header-anchor" href="#frontend-coverage-and-ownership-map" aria-label="Permalink to “Frontend coverage and ownership map”">​</a></h1><p>Review date: <strong>2026-10-27</strong>. This map reconciles the essential frontend path against audit R2-01/05/06/09/10/11. Coverage evidence comes from explanations, worked code and stated failure contracts—not a heading count. Existing reference URLs stay in place; the new frontend home orders them instead of making duplicate textbook copies.</p><h2 id="essential-concept-records" tabindex="-1">Essential concept records <a class="header-anchor" href="#essential-concept-records" aria-label="Permalink to “Essential concept records”">​</a></h2><p>Depth: foundational explanation plus a worked boundary/counterexample unless otherwise stated. Each record names its prerequisite and a separate practice stage. Live integration, performance, assistive and learner evidence remain distinct from material completion.</p><h3 id="document-semantics-forms-and-names" tabindex="-1">Document semantics, forms and names <a class="header-anchor" href="#document-semantics-forms-and-names" aria-label="Permalink to “Document semantics, forms and names”">​</a></h3><p><strong>Prerequisite:</strong> HTML basics. <strong>Teaching owner:</strong> <a href="./../senior_growth/A11y/What_is_semantic_HTML.html">Native form/table/disclosure</a>.</p><p><strong>Inspected explanation/worked boundary:</strong> Native validation, FormData, name/description precedence, numeric table sort, cleanup. <strong>Practice:</strong> F01 in <a href="./../practice/frontend/">the sequence</a>.</p><h3 id="focus-modal-and-async-feedback" tabindex="-1">Focus, modal and async feedback <a class="header-anchor" href="#focus-modal-and-async-feedback" aria-label="Permalink to “Focus, modal and async feedback”">​</a></h3><p><strong>Prerequisite:</strong> Native controls. <strong>Teaching owner:</strong> <a href="./../senior_growth/A11y/Can_you_provide_some_examples_for_a11y.html">Dialog/media/form notifications</a>.</p><p><strong>Inspected explanation/worked boundary:</strong> Heading versus field focus, associated errors and surviving success region; no reader pass inferred. <strong>Practice:</strong> F01 in <a href="./../practice/frontend/">the sequence</a>.</p><h3 id="accessibility-evaluation" tabindex="-1">Accessibility evaluation <a class="header-anchor" href="#accessibility-evaluation" aria-label="Permalink to “Accessibility evaluation”">​</a></h3><p><strong>Prerequisite:</strong> Semantics/input model. <strong>Teaching owner:</strong> <a href="./../senior_growth/A11y/Can_we_test%2C_measure_a11y_somehow.html">Evaluation and evidence</a>.</p><p><strong>Inspected explanation/worked boundary:</strong> Rule scans versus keyboard/reader/reflow; scoped findings and retests. <strong>Practice:</strong> F01 in <a href="./../practice/frontend/">the sequence</a>.</p><h3 id="browser-processing-and-security" tabindex="-1">Browser processing and security <a class="header-anchor" href="#browser-processing-and-security" aria-label="Permalink to “Browser processing and security”">​</a></h3><p><strong>Prerequisite:</strong> HTML/URLs. <strong>Teaching owner:</strong> <a href="./html-browser.html">Browser lifecycle</a> and <a href="./../senior_growth/Other/Cross_Browser_Progressive_Enhancement.html">HTML-first search</a>.</p><p><strong>Inspected explanation/worked boundary:</strong> Parser/script/render distinction; no-JS GET, failure fallback, owned optional fetch. <strong>Practice:</strong> F01/F03 in <a href="./../practice/frontend/">the sequence</a>.</p><h3 id="box-model-layout-and-responsive-sizing" tabindex="-1">Box model, layout and responsive sizing <a class="header-anchor" href="#box-model-layout-and-responsive-sizing" aria-label="Permalink to “Box model, layout and responsive sizing”">​</a></h3><p><strong>Prerequisite:</strong> Document flow. <strong>Teaching owner:</strong> <a href="./../senior_growth/CSS/layout-and-responsive-design.html">Layout mechanisms</a>.</p><p><strong>Inspected explanation/worked boundary:</strong> 200/244/156 boxes, flex/grid intrinsic minimums, stacking, container fallback and CLS limits. <strong>Practice:</strong> F02 in <a href="./../practice/frontend/">the sequence</a>.</p><h3 id="cascade-selectors-and-interaction-states" tabindex="-1">Cascade, selectors and interaction states <a class="header-anchor" href="#cascade-selectors-and-interaction-states" aria-label="Permalink to “Cascade, selectors and interaction states”">​</a></h3><p><strong>Prerequisite:</strong> CSS rules. <strong>Teaching owner:</strong> <a href="./../senior_growth/CSS/Can_you_describe_what_is_CSS_Specificity.html">Cascade/specificity</a>.</p><p><strong>Inspected explanation/worked boundary:</strong> Layers before tuples, important reversal, where/is/has, visible focus and forced colors. <strong>Practice:</strong> F02 in <a href="./../practice/frontend/">the sequence</a>.</p><h3 id="units-themes-and-styling-ownership" tabindex="-1">Units, themes and styling ownership <a class="header-anchor" href="#units-themes-and-styling-ownership" aria-label="Permalink to “Units, themes and styling ownership”">​</a></h3><p><strong>Prerequisite:</strong> Sizing/cascade. <strong>Teaching owner:</strong> <a href="./../senior_growth/CSS/Difference_between_pixels%2C_ems_or_rems_Which_one_we_should_use.html">Units</a>; <a href="./../senior_growth/CSS/styling_react_apps.html">Runtime themes</a>; <a href="./../senior_growth/CSS/How_would_you_organize_CSS_on_huge_project.html">Architecture</a>.</p><p><strong>Inspected explanation/worked boundary:</strong> Relative units, nested variable aliases, Sass versus runtime and SSR first-theme agreement. <strong>Practice:</strong> F02/F06 in <a href="./../practice/frontend/">the sequence</a>.</p><h3 id="bindings-closures-and-this" tabindex="-1">Bindings, closures and this <a class="header-anchor" href="#bindings-closures-and-this" aria-label="Permalink to “Bindings, closures and this”">​</a></h3><p><strong>Prerequisite:</strong> JS functions. <strong>Teaching owner:</strong> <a href="./../senior_growth/General_ES6/Explain_JavaScript_Code_Execution_177e8106c24d80a0817df62da9bac253.html">Execution</a>; <a href="./../senior_growth/General_ES6/What_is_the_temporal_dead_zone_Why_is_this_happeni_177e8106c24d80d991b7caa84eaad6b6.html">Lexical TDZ</a>.</p><p><strong>Inspected explanation/worked boundary:</strong> Worked binding fixture, retained lexical state and event-time/current-value ownership. <strong>Practice:</strong> F03 in <a href="./../practice/frontend/">the sequence</a>.</p><h3 id="identity-equality-and-pure-updates" tabindex="-1">Identity, equality and pure updates <a class="header-anchor" href="#identity-equality-and-pure-updates" aria-label="Permalink to “Identity, equality and pure updates”">​</a></h3><p><strong>Prerequisite:</strong> Objects/functions. <strong>Teaching owner:</strong> <a href="./../senior_growth/General_ES6/What_is_the_difference_between_&#39;null&#39;_and_&#39;undefin_177e8106c24d80f98ff8c802efb7ff70.html">Equality/nullish</a>; <a href="./../senior_growth/General_ES6/What_are_pure_impure_functions_177e8106c24d80d19ebde80bcd1b5b50.html">Pure/effect shell</a>.</p><p><strong>Inspected explanation/worked boundary:</strong> Object.is/SameValueZero distinctions, shallow copying and alias limits; CS owns collection cost. <strong>Practice:</strong> F03 in <a href="./../practice/frontend/">the sequence</a>.</p><h3 id="promises-scheduling-and-lifetime" tabindex="-1">Promises, scheduling and lifetime <a class="header-anchor" href="#promises-scheduling-and-lifetime" aria-label="Permalink to “Promises, scheduling and lifetime”">​</a></h3><p><strong>Prerequisite:</strong> Execution/closures. <strong>Teaching owner:</strong> <a href="./../senior_growth/General_ES6/What_is_a_Promise_177e8106c24d80b3989df334146152f6.html">Promises</a>; <a href="./../senior_growth/General_ES6/Understanding_async_await_in_JavaScript_177e8106c24d806fb457f53520e2c087.html">Async lifetimes</a>; <a href="./../senior_growth/General_ES6/What_are_the_tasks_microtasks_177e8106c24d804f94a8c0f84060cdf2.html">Checkpoints</a>.</p><p><strong>Inspected explanation/worked boundary:</strong> Resolution versus completion, peer cancellation/draining, deadline/body limits and starvation. <strong>Practice:</strong> F03 in <a href="./../practice/frontend/">the sequence</a>.</p><h3 id="browser-state-and-api-cleanup" tabindex="-1">Browser state and API cleanup <a class="header-anchor" href="#browser-state-and-api-cleanup" aria-label="Permalink to “Browser state and API cleanup”">​</a></h3><p><strong>Prerequisite:</strong> Events/async. <strong>Teaching owner:</strong> <a href="./../senior_growth/General_ES6/Could_you_please_describe_with_which_Browser_APIs__177e8106c24d802caa88e9916f01fc53.html">DOM/events/origin</a>; <a href="./../senior_growth/General_ES6/Browser_Storage_and_Offline_Drafts.html">Offline draft reference</a>.</p><p><strong>Inspected explanation/worked boundary:</strong> Delegation/message schema, storage scope/expiry/conflict and IndexedDB connection ownership. <strong>Practice:</strong> F03; optional native-IDB extension in <a href="./../practice/frontend/">the sequence</a>.</p><h3 id="strict-narrowing-and-runtime-boundaries" tabindex="-1">Strict narrowing and runtime boundaries <a class="header-anchor" href="#strict-narrowing-and-runtime-boundaries" aria-label="Permalink to “Strict narrowing and runtime boundaries”">​</a></h3><p><strong>Prerequisite:</strong> JS values. <strong>Teaching owner:</strong> <a href="./../senior_growth/TypeScript/What_are_the_different_types_of_TypeScript_(Built-in_%26_User-defined).html">Structural/unknown types</a>; <a href="./../senior_growth/TypeScript/What_&quot;Strict_NULL_check_mode&quot;_means.html">Presence</a>; <a href="./../senior_growth/TypeScript/Explain_the_purpose_of_the_&quot;never&quot;_type_in_TypeScript_How_it&#39;s_different_from_&quot;void&quot;.html">Exhaustive states</a>.</p><p><strong>Inspected explanation/worked boundary:</strong> Truthful guards, absence versus undefined, erased/shallow readonly, unknown JSON and never. <strong>Practice:</strong> F04/P-330 in <a href="./../practice/frontend/">the sequence</a>.</p><h3 id="generics-modules-and-compatibility" tabindex="-1">Generics, modules and compatibility <a class="header-anchor" href="#generics-modules-and-compatibility" aria-label="Permalink to “Generics, modules and compatibility”">​</a></h3><p><strong>Prerequisite:</strong> Strict basic types. <strong>Teaching owner:</strong> <a href="./../senior_growth/TypeScript/Generics.html">Generic relations</a>; <a href="./../senior_growth/TypeScript/Can_we_write_code_in_TS_if_we_would_like_to_support_older_browsers.html">Target/API policy</a>.</p><p><strong>Inspected explanation/worked boundary:</strong> Dependent key result, expected-invalid calls; advanced conditional/variance examples optional. <strong>Practice:</strong> F04 in <a href="./../practice/frontend/">the sequence</a>.</p><h3 id="react-render-queue-and-key-identity" tabindex="-1">React render, queue and key identity <a class="header-anchor" href="#react-render-queue-and-key-identity" aria-label="Permalink to “React render, queue and key identity”">​</a></h3><p><strong>Prerequisite:</strong> JS/TS snapshots. <strong>Teaching owner:</strong> <a href="./../senior_growth/React/Change_Detection_in_React.html">Render owner</a>; <a href="./../senior_growth/React/Could_you_explain_how_change_detection_mechanism_works_in_React%2C_tradeoffs_and_benefits.html">Entity-identity companion</a>.</p><p><strong>Inspected explanation/worked boundary:</strong> Replacement versus updater queue, commit versus paint, keyed draft through reorder. <strong>Practice:</strong> F05/P-329 in <a href="./../practice/frontend/">the sequence</a>.</p><h3 id="effects-refs-state-ownership-and-races" tabindex="-1">Effects, refs, state ownership and races <a class="header-anchor" href="#effects-refs-state-ownership-and-races" aria-label="Permalink to “Effects, refs, state ownership and races”">​</a></h3><p><strong>Prerequisite:</strong> React rendering. <strong>Teaching owner:</strong> <a href="./../senior_growth/React/What_Are_React_Hooks_Good_For_Rules_of_Hooks.html">Hooks</a>; <a href="./../senior_growth/React/Lifecycle_Methods_and_the_Virtual_DOM.html">Lifetimes</a>.</p><p><strong>Inspected explanation/worked boundary:</strong> Pure reducer, context scope, external-store contract, cleanup and ignored-abort ownership. <strong>Practice:</strong> F05 in <a href="./../practice/frontend/">the sequence</a>.</p><h3 id="forms-remote-state-and-mutations" tabindex="-1">Forms, remote state and mutations <a class="header-anchor" href="#forms-remote-state-and-mutations" aria-label="Permalink to “Forms, remote state and mutations”">​</a></h3><p><strong>Prerequisite:</strong> Hooks/validation. <strong>Teaching owner:</strong> <a href="./../senior_growth/React/complex-forms-and-data.html">Forms/drafts</a>; <a href="./../senior_growth/React/Submission_Idempotency.html">Submission intent</a>.</p><p><strong>Inspected explanation/worked boundary:</strong> Monotonic confirmed record plus pending overlay, shared keys, wizard validation/focus and uncertain commit. <strong>Practice:</strong> F05/P-328 in <a href="./../practice/frontend/">the sequence</a>.</p><h3 id="composition-hocs-and-dialogs" tabindex="-1">Composition, HOCs and dialogs <a class="header-anchor" href="#composition-hocs-and-dialogs" aria-label="Permalink to “Composition, HOCs and dialogs”">​</a></h3><p><strong>Prerequisite:</strong> Native semantics + React state. <strong>Teaching owner:</strong> <a href="./../senior_growth/React/Composition_and_Higher-Order_Components_(HOCs)_in.html">Slots/tabs/adapter</a>; <a href="./../senior_growth/React/Modals_in_react%2C_portal_or_not.html">Native dialog</a>.</p><p><strong>Inspected explanation/worked boundary:</strong> Controlled ID selection/keyboard model, forwarded ref/props, stable component type and focus recovery. <strong>Practice:</strong> F05 in <a href="./../practice/frontend/">the sequence</a>.</p><h3 id="memoization-and-performance" tabindex="-1">Memoization and performance <a class="header-anchor" href="#memoization-and-performance" aria-label="Permalink to “Memoization and performance”">​</a></h3><p><strong>Prerequisite:</strong> Correct identity first. <strong>Teaching owner:</strong> <a href="./../senior_growth/React/What_is_memoization_and_how_to_achieve_it_in_React.html">Mechanism owner</a>; <a href="./../senior_growth/React/react_memo.html">Comparator companion</a>; <a href="./../senior_growth/React/performance_potimization.html">Experiment companion</a>.</p><p><strong>Inspected explanation/worked boundary:</strong> Discardable cache versus state, callback comparison, debounce cleanup and measured workloads. <strong>Practice:</strong> F05 in <a href="./../practice/frontend/">the sequence</a>.</p><h3 id="test-boundaries" tabindex="-1">Test boundaries <a class="header-anchor" href="#test-boundaries" aria-label="Permalink to “Test boundaries”">​</a></h3><p><strong>Prerequisite:</strong> Async component behavior. <strong>Teaching owner:</strong> <a href="./../senior_growth/React/React_testing.html">Component checks</a>; <a href="./../senior_growth/EngX_Quality/Large_Data_Workflow.html">Bounded table</a>.</p><p><strong>Inspected explanation/worked boundary:</strong> Three SaveButton cases; six race/scope/pagination checks; real browser observations separate. <strong>Practice:</strong> F05/P-329 in <a href="./../practice/frontend/">the sequence</a>.</p><h3 id="next-boundaries-and-route-states" tabindex="-1">Next boundaries and route states <a class="header-anchor" href="#next-boundaries-and-route-states" aria-label="Permalink to “Next boundaries and route states”">​</a></h3><p><strong>Prerequisite:</strong> React + HTTP. <strong>Teaching owner:</strong> <a href="./../senior_growth/React/next-app-router.html">App Router</a>.</p><p><strong>Inspected explanation/worked boundary:</strong> Safe DTO/type-only import, deterministic hydration, loading/absence/error and stable retry API. <strong>Practice:</strong> F06 in <a href="./../practice/frontend/">the sequence</a>.</p><h3 id="caches-assets-and-deployment" tabindex="-1">Caches, assets and deployment <a class="header-anchor" href="#caches-assets-and-deployment" aria-label="Permalink to “Caches, assets and deployment”">​</a></h3><p><strong>Prerequisite:</strong> Server/client boundary. <strong>Teaching owner:</strong> <a href="./../senior_growth/React/next-deployment-and-assets.html">Delivery</a>; <a href="./next.html">cache-model decision</a>.</p><p><strong>Inspected explanation/worked boundary:</strong> Previous cache model explicitly selected; public/private freshness, ISR versus cron, export limitations. <strong>Practice:</strong> F06 in <a href="./../practice/frontend/">the sequence</a>.</p><h3 id="authentication-and-mutation-authority" tabindex="-1">Authentication and mutation authority <a class="header-anchor" href="#authentication-and-mutation-authority" aria-label="Permalink to “Authentication and mutation authority”">​</a></h3><p><strong>Prerequisite:</strong> HTTP/cookies/SQL. <strong>Teaching owner:</strong> <a href="./../senior_growth/React/next-server-security.html">Server security</a>.</p><p><strong>Inspected explanation/worked boundary:</strong> Opaque session hash, owner/version write, Origin/CSRF checks, bounded body, safe errors. <strong>Practice:</strong> F06/P-330; real DB integration outstanding in <a href="./../practice/frontend/">the sequence</a>.</p><h3 id="component-contracts-and-ui-architecture" tabindex="-1">Component contracts and UI architecture <a class="header-anchor" href="#component-contracts-and-ui-architecture" aria-label="Permalink to “Component contracts and UI architecture”">​</a></h3><p><strong>Prerequisite:</strong> State/accessibility. <strong>Teaching owner:</strong> <a href="./../senior_growth/React/design-system-contracts.html">Contracts/tokens</a>; <a href="./../senior_growth/React/design-system-release.html">Consumer release</a>; <a href="./../senior_growth/React/application_struvture.html">Application ports</a>.</p><p><strong>Inspected explanation/worked boundary:</strong> Native Button/ref API, deterministic token output, narrow migration, import-rule limits and rollback. <strong>Practice:</strong> F06 in <a href="./../practice/frontend/">the sequence</a>.</p><h2 id="duplication-decisions" tabindex="-1">Duplication decisions <a class="header-anchor" href="#duplication-decisions" aria-label="Permalink to “Duplication decisions”">​</a></h2><ul><li><strong>Render/queues versus identity:</strong> retain both change-detection pages; the first owns scheduling/snapshots, the question companion owns editable keys and reconciliation trade-offs. Stable keys do not skip rendering automatically.</li><li><strong>HOC versus composition:</strong> the short HOC page remains a decision guide; the composition page owns controlled tabs and typed prop/ref transparency. Class integration, static fields, collisions and adapter lifetime are retained.</li><li><strong>Memoization:</strong> the mechanism page owns memo/useMemo/useCallback; the comparator page retains callback correctness; performance examples retain debounce/measurement context. CS owns algorithmic memoization and complexity. No blanket merge deletes distinct examples.</li><li><strong>CSS:</strong> the comparison page chooses tools, architecture owns layer/token migration, and React styling owns runtime theme/SSR agreement. Build-time Sass variables and runtime custom properties are different mechanisms.</li><li><strong>Shared server/algorithm material:</strong> link completed Node/CS explanations. No copies of database/stream/complexity courses were added. The applied-AI streaming UI port remains untouched.</li></ul><h2 id="scope-and-remaining-catalogue" tabindex="-1">Scope and remaining catalogue <a class="header-anchor" href="#scope-and-remaining-catalogue" aria-label="Permalink to “Scope and remaining catalogue”">​</a></h2><p>The essential reading lane covers HTML/CSS/browser/accessibility → JS/TS → React → Next/UI contracts. Existing interview summaries, framework comparisons, class/prototype/year catalogues and optional tools remain reference context, with focused prose/assignment cleanup. This is not a claim to have independently re-certified every external course, historical benchmark, package transitive dependency or optional platform adapter.</p><p>Optional extensions: native IndexedDB upgrade/concurrency runs, service-worker lifecycle, custom elements/Shadow DOM interop, advanced generic transformations, Cache Components migration, real multi-instance caching, virtualization/composite grids, design-system publishing and microfrontends. Choose them for an actual product need. Their retained procedures do not imply an executed integration.</p><p><a href="./">Reading order</a> · <a href="./../workbench/frontend/">Workbench</a> · <a href="./../practice/frontend/">Practice</a> · <a href="./verification.html">Executed checks and limits</a></p>',79)])])}const u=a(o,[["render",s]]);export{g as __pageData,u as default};
